    query=normalize(cells_color(1,sep+1,h))
    fs=[lambda r,c:(r,c),lambda r,c:(c,-r),lambda r,c:(-r,-c),lambda r,c:(-c,r),lambda r,c:(r,-c),lambda r,c:(-r,c),lambda r,c:(c,r),lambda r,c:(-c,-r)]
    f=fs[0]
