        if q==key: f=g;break
    def trans(shape):
        q={f(r,c) for r,c in shape};mr=min(r for r,c in q);mc=min(c for r,c in q);return {(r-mr,c-mc) for r,c in q}
    color_shape=trans(color_shape); query=trans(query)
